// Whisper STT voice input — accepts a voice memo upload, transcribes
// via Ollama-hosted Whisper (or external Whisper-compatible endpoint),
// then writes the transcript to /data/chatin/ in the same shape as
// workflow 08 captures from Synology Chat. Foundation Agent picks it up
// on the next cron run as a regular @nas thought.
//
// Per AI-FOUNDATION-INTERNAL-OPERATIONS: voice in, text out, route
// through existing pipeline. Browsers are for humans; this turns the
// phone microphone into a sovereign capture surface.
//
// Per TLC firewall: voice memos may contain clinical content. The
// Whisper instance MUST be local-hosted on NAS, never cloud. Failure
// to reach local Whisper = capture saves the audio raw and surfaces a
// ntfy alert; never falls back to cloud STT.
//
// POST body shape:
//   { sender, audio_base64, mime_type?, source? }
// audio_base64 is the recorded audio file (typical: webm or wav).
//
// Returns:
//   { ok, id, transcript, captured_at }

const fs = require('fs');
const path = require('path');

const CHATIN_DIR = '/data/chatin';
const WHISPER_URL = 'http://whisper:9000/asr';
const NTFY_BASE = 'http://ntfy:80';
const NTFY_TOPIC = 'poetech-voice';

try { fs.mkdirSync(CHATIN_DIR, { recursive: true }); } catch (_) {}

const input = $input.first().json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;

const sender = (body.sender || 'unknown').toString().trim().toLowerCase();
const audioB64 = (body.audio_base64 || '').toString();
const mimeType = (body.mime_type || 'audio/webm').toString();
const source = (body.source || 'voice-memo').toString();

if (!audioB64 || audioB64.length < 100) {
  return [{ json: { ok: false, error: 'audio_base64 is required (or audio too short)' } }];
}

const audioBuf = Buffer.from(audioB64, 'base64');
const capturedAt = new Date().toISOString();
const id = 'v-' + capturedAt.replace(/[:.]/g, '-') + '-' + Math.floor(Math.random() * 10000);

// Transcribe via local Whisper instance.
// Whisper-ASR-Webservice (common Docker image) accepts multipart/form-data.
// Local-only; never falls back to cloud.
// NOTE (2026-06-13 OPEN-6): this multipart fetch + FormData/Blob is NOT yet
// converted to this.helpers.httpRequest - the sandbox lacks fetch/FormData,
// so it throws and degrades to the save-audio + ntfy-alert fallback below
// (which IS now sandbox-safe). A proper multipart httpRequest needs a live
// Whisper service to validate; tracked as a separate follow-up.
let transcript = '';
let whisperOk = false;
try {
  const formData = new FormData();
  const blob = new Blob([audioBuf], { type: mimeType });
  formData.append('audio_file', blob, 'voice.webm');
  const r = await fetch(WHISPER_URL + '?task=transcribe&output=json', {
    method: 'POST',
    body: formData,
    signal: AbortSignal.timeout(120000)
  });
  if (r.ok) {
    const data = await r.json();
    transcript = (data.text || '').trim();
    whisperOk = transcript.length > 0;
  }
} catch (e) {
  // Local Whisper unreachable. Per TLC firewall, do NOT fall back to cloud.
  // Save the raw audio for later transcription and surface an alert.
}

if (!whisperOk) {
  // Save raw audio to chatin so it's not lost. Filename signals it needs
  // manual transcription.
  const audioFn = path.join(CHATIN_DIR, id + '.audio.' + (mimeType.split('/')[1] || 'webm'));
  try { fs.writeFileSync(audioFn, audioBuf); } catch (_) {}
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: NTFY_BASE + '/' + NTFY_TOPIC,
      headers: { 'Title': 'Voice capture - transcription pending', 'Priority': '3', 'Tags': 'microphone', 'Content-Type': 'text/plain' },
      body: 'Voice memo from ' + sender + ' saved to ' + audioFn + '. Local Whisper unreachable; will retry on next attempt.',
      timeout: 5000
    });
  } catch (_) {}
  return [{ json: { ok: false, error: 'whisper unreachable; audio saved for later', id, audio_path: audioFn } }];
}

// Write transcript to /data/chatin/ in the same shape workflow 08 uses.
// This lets Foundation Agent (workflow 27) pick it up on next cron as if
// it were a regular @nas chat message.
const chatinFn = id + '__' + sender + '__voice.json';
const record = {
  source: 'voice-memo',
  captured_at: capturedAt,
  sender,
  channel: 'voice',
  text: transcript,
  raw_text: transcript,
  file: chatinFn
};
try { fs.writeFileSync(path.join(CHATIN_DIR, chatinFn), JSON.stringify(record, null, 2)); }
catch (e) { return [{ json: { ok: false, error: 'write failed: ' + String(e) } }]; }

return [{ json: { ok: true, id, transcript, captured_at: capturedAt, message: 'Captured. Foundation Agent will process on next cron.' } }];
